import random

def kth_largest(nums: list[int], k: int) -> int:
    """
    This function finds the k-th largest element in an unsorted list using 
    the Quickselect algorithm, which has an average time complexity of O(n).

    Args:
    nums (list[int]): The unsorted list of integers.
    k (int): The k-th largest element to find (1-indexed).

    Returns:
    int: The k-th largest element in the list.
    """

    def partition(left, right, pivot_index):
        pivot_value = nums[pivot_index]
        # Move pivot to the end
        nums[pivot_index], nums[right] = nums[right], nums[pivot_index]
        store_index = left

        for i in range(left, right):
            if nums[i] > pivot_value:  # We want k-th largest, so we use >
                nums[store_index], nums[i] = nums[i], nums[store_index]
                store_index += 1

        # Move pivot to its final place
        nums[right], nums[store_index] = nums[store_index], nums[right]
        return store_index

    def quickselect(left, right, k_th):
        if left == right:
            return nums[left]

        pivot_index = random.randint(left, right)
        pivot_index = partition(left, right, pivot_index)

        if k_th == pivot_index:
            return nums[k_th]
        elif k_th < pivot_index:
            return quickselect(left, pivot_index - 1, k_th)
        else:
            return quickselect(pivot_index + 1, right, k_th)

    return quickselect(0, len(nums) - 1, k - 1)

